-- IMPORTANTE: cualquier incidencia que tengas registrada con la categoria
-- 'Prestamo de Libros' o con alguna de las ubicaciones viejas (Edificio A,
-- Edificio B, Biblioteca Central, etc.) se eliminara en cascada junto con
-- sus comentarios, historial, asignaciones y adjuntos, porque esas filas
-- ya no van a existir. Si tienes incidencias reales que quieras conservar,
-- anota su informacion antes de correr este script.

DELETE FROM categorias WHERE nombre_categoria = 'Préstamo de Libros';

TRUNCATE TABLE ubicaciones RESTART IDENTITY CASCADE;

